function limpiarTexto(texto) {
  return (texto || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[¿?.,;:()"']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function contieneAlguna(texto, palabras) {
  return palabras.some(p => texto.includes(p));
}

function puntuacionFaq(faq, text, categoriaEmail) {
  let score = 0;

  const pregunta = limpiarTexto(faq.pregunta_tipo);
  const respuesta = limpiarTexto(faq.respuesta_oficial);
  const cuandoUsar = limpiarTexto(faq.cuando_usar);
  const cuandoNoUsar = limpiarTexto(faq.cuando_no_usar);
  const categoriaFaq = limpiarTexto(faq.categoria_origen);

  const bloques = [pregunta, respuesta, cuandoUsar, cuandoNoUsar, categoriaFaq];

  for (const bloque of bloques) {
    const palabras = bloque.split(' ').filter(p => p.length > 3);
    for (const palabra of palabras) {
      if (text.includes(palabra)) score += 1;
    }
  }

  if (categoriaEmail && categoriaFaq.includes(categoriaEmail)) {
    score += 4;
  }

  const esFacturacion = contieneAlguna(text, [
    'factura', 'facturacion', 'cargo', 'cobro', 'pago', 'importe', 'recibo'
  ]);

  const esPrecio = contieneAlguna(text, [
    'precio', 'presupuesto', 'coste', 'tarifa'
  ]);

  const esFormacion = contieneAlguna(text, [
    'formacion', 'workshop', 'workshops', 'taller'
  ]);

  const esSoporte = contieneAlguna(text, [
    'soporte', 'ayuda', 'problema', 'error', 'incidencia'
  ]);

  const esIA = contieneAlguna(text, [
    'ia', 'inteligencia artificial'
  ]);

  if (esFacturacion) {
    if (
      contieneAlguna(pregunta, ['factura', 'facturacion', 'cargo', 'cobro', 'pago']) ||
      contieneAlguna(respuesta, ['factura', 'facturacion', 'cargo', 'cobro', 'pago']) ||
      contieneAlguna(cuandoUsar, ['factura', 'facturacion', 'cargo', 'cobro', 'pago']) ||
      categoriaFaq.includes('facturacion')
    ) {
      score += 6;
    }

    if (categoriaFaq.includes('lead') || categoriaFaq.includes('ventas')) {
      score -= 4;
    }
  }

  if (esPrecio) {
    if (
      contieneAlguna(pregunta, ['precio', 'tarifa', 'coste', 'presupuesto']) ||
      contieneAlguna(respuesta, ['precio', 'tarifa', 'coste', 'presupuesto'])
    ) {
      score += 5;
    }
  }

  if (esFormacion) {
    if (
      contieneAlguna(pregunta, ['formacion', 'workshop', 'taller']) ||
      contieneAlguna(respuesta, ['formacion', 'workshop', 'taller'])
    ) {
      score += 5;
    }
  }

  if (esSoporte) {
    if (
      categoriaFaq.includes('soporte') ||
      contieneAlguna(cuandoUsar, ['soporte', 'ayuda', 'problema', 'error', 'incidencia'])
    ) {
      score += 4;
    }
  }

  if (esIA) {
    if (
      contieneAlguna(pregunta, ['ia', 'inteligencia artificial']) ||
      contieneAlguna(respuesta, ['ia', 'inteligencia artificial'])
    ) {
      score += 3;
    }
  }

  return score;
}

