function scoreHistorico(item, text) {
  let score = 0;

  const categoria = limpiarTexto(item.categoria);
  const intencion = limpiarTexto(item.intencion);
  const emailOriginal = limpiarTexto(item.email_original);
  const respuesta = limpiarTexto(item.respuesta_aprobada);
  const tags = limpiarTexto(item.tags);

  const bloques = [categoria, intencion, emailOriginal, respuesta, tags];

  for (const bloque of bloques) {
    const palabras = bloque.split(' ').filter(p => p.length > 3);
    for (const palabra of palabras) {
      if (text.includes(palabra)) score += 1;
    }
  }

  if (
    text.includes('precio') ||
    text.includes('presupuesto') ||
    text.includes('coste') ||
    text.includes('tarifa')
  ) {
    if (
      emailOriginal.includes('precio') ||
      respuesta.includes('tarifa') ||
      tags.includes('precio')
    ) {
      score += 5;
    }
  }

  if (
    text.includes('formacion') ||
    text.includes('workshop') ||
    text.includes('workshops')
  ) {
    if (
      emailOriginal.includes('formacion') ||
      respuesta.includes('workshop') ||
      tags.includes('formacion')
    ) {
      score += 5;
    }
  }

  if (
    text.includes('soporte') ||
    text.includes('ayuda') ||
    text.includes('problema') ||
    text.includes('error')
  ) {
    if (
      categoria.includes('soporte') ||
      tags.includes('soporte')
    ) {
      score += 4;
    }
  }

  return score;
}

